const makeWithBrokers = (brokers: {
  readonly primary: Effect.Success<ReturnType<typeof makePrimaryBroker>>;
  readonly bearer: Effect.Success<ReturnType<typeof makeBearerBroker>>;
  readonly relay: Effect.Success<ReturnType<typeof makeRelayBroker>>;
  readonly ssh: Effect.Success<ReturnType<typeof makeSshBroker>>;
}) => Effect.gen(function* () {
  const { primary, bearer, relay, ssh } = brokers;

export const make = Effect.gen(function* () {
  return yield* makeWithBrokers({ primary: yield* makePrimaryBroker(), bearer: yield* makeBearerBroker(),
    relay: yield* makeRelayBroker(), ssh: yield* makeSshBroker() });
});
export const makeBearer = Effect.gen(function* () {
  const unavailable = (_target: unknown) => Effect.fail(new ConnectionBlockedError({
    reason: "unsupported", detail: "This host accepts only its admitted bearer connection.",
  }));
  return yield* makeWithBrokers({ primary: unavailable, bearer: yield* makeBearerBroker(),
    relay: unavailable, ssh: unavailable });
});
export const layer = Layer.effect(ConnectionResolver, make);
export const layerBearer = Layer.effect(ConnectionResolver, makeBearer);
